document.addEventListener("alpine:init",()=>{Alpine.data("pwdStrength",()=>({colours:["bg-gray-500","bg-red-500","bg-orange-500","bg-yellow-500","bg-green-500"],zxcvbn:null,pwdok:!1,init:function(){this.pwd1="",this.pwd2="",this.zxcvbn=null,this.score=0,this.warn1="",this.warn2="",this.pwdok=!1,this.touch=!1,import("/js/npm/zxcvbn/zxcvbn.js").then(module=>{this.zxcvbn=module.default||module}).catch(err=>{this.zxcvbn=null,console.error("Failed to load zxcvbn:",err)})},checkPassword1:function(){var result;""===this.pwd1?(this.score=0,this.warn1=""):this.pwd1.length<8?(this.score=1,this.warn1="Password must be at least 8 characters long."):125<this.pwd1.length?(this.score=1,this.warn1="Password must be less than 125 characters long."):this.zxcvbn?(result=this.zxcvbn.zxcvbn(this.pwd1),this.score=result?.score||0,this.warn1=result?.feedback?.warning||""):(this.score=3,this.warn1="unable to check password strength"),this.warn2=this.touch&&this.pwd1!==this.pwd2?"Passwords do not match.":"",this.checkOK()},checkPassword2:function(){this.touch=""!==this.pwd2,this.warn2=this.touch&&this.pwd1!==this.pwd2?"Passwords do not match.":"",this.checkOK()},checkOK:function(){this.pwdok=this.touch&&8<=this.pwd1.length&&2<=this.score&&this.pwd1===this.pwd2}}))});